"""Post-processing for 72B zero-shot NER: 5-signal evaluation + entity construction."""

import json
import os
import sys
import statistics
from collections import Counter, defaultdict

import numpy as np
from scipy.stats import spearmanr, kendalltau, rankdata

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from consistency import compute_all_consistency_scores
from evaluation import per_instance_f1

BASE = "/root/autodl-tmp/struct_self_consist_ie"
OUTPUT_BASE = f"{BASE}/output/72b_zeroshot"

DATASETS = {
    "scierc": f"{OUTPUT_BASE}/scierc/samples.jsonl",
    "conll2003": f"{OUTPUT_BASE}/conll2003/samples.jsonl",
    "fewnerd": f"{OUTPUT_BASE}/fewnerd/samples.jsonl",
}

SUBTASK = "ner"


def load_data(path, gold_filter=True):
    instances = []
    with open(path) as f:
        for line in f:
            if not line.strip():
                continue
            obj = json.loads(line)
            if gold_filter and len(obj["gold"].get("entities", [])) == 0:
                continue
            instances.append(obj)
    return instances


def compute_entity_f1(pred_entities, gold_entities):
    pred = {(e["start"], e["end"], e["type"]) for e in pred_entities}
    gold = {(e["start"], e["end"], e["type"]) for e in gold_entities}
    if not gold and not pred:
        return 1.0
    if not gold or not pred:
        return 0.0
    tp = len(pred & gold)
    if tp == 0:
        return 0.0
    p = tp / len(pred)
    r = tp / len(gold)
    return 2 * p * r / (p + r)


def compute_exact_match_rate(samples):
    keys = [frozenset((e["text"], e["type"]) for e in s.get("entities", [])) for s in samples]
    if not keys:
        return 0.0
    counter = Counter(keys)
    return counter.most_common(1)[0][1] / len(samples)


def compute_voting_confidence(samples):
    N = len(samples)
    if N == 0:
        return 0.0
    counter = Counter()
    for s in samples:
        for e in s.get("entities", []):
            counter[(e["text"], e["type"])] += 1
    if not counter:
        return 0.0
    return float(np.mean([v / N for v in counter.values()]))


def compute_mean_logprob(samples, inst):
    lps = []
    for i, s in enumerate(samples):
        if "mean_logprob" in s:
            lps.append(s["mean_logprob"])
        elif "logprobs" in inst and i < len(inst["logprobs"]):
            lps.append(inst["logprobs"][i])
    lps = [lp for lp in lps if np.isfinite(lp)]
    return float(np.mean(lps)) if lps else float("nan")


def safe_auroc(scores, labels):
    scores = np.asarray(scores, dtype=float)
    labels = np.asarray(labels, dtype=int)
    if len(np.unique(labels)) < 2:
        return float("nan")
    n_pos = np.sum(labels == 1)
    n_neg = np.sum(labels == 0)
    if n_pos == 0 or n_neg == 0:
        return float("nan")
    ranks = rankdata(scores)
    u = ranks[labels == 1].sum() - n_pos * (n_pos + 1) / 2
    return float(u / (n_pos * n_neg))


def safe_spearman(x, y):
    x, y = np.asarray(x, dtype=float), np.asarray(y, dtype=float)
    mask = np.isfinite(x) & np.isfinite(y)
    x, y = x[mask], y[mask]
    if len(x) < 3:
        return float("nan")
    return float(spearmanr(x, y).statistic)


def bootstrap_ci(values, n_boot=2000, seed=42):
    rng = np.random.RandomState(seed)
    arr = np.array(values)
    n = len(arr)
    if n == 0:
        return {"mean": 0.0, "ci_lo": 0.0, "ci_hi": 0.0}
    boot_means = np.array([arr[rng.randint(0, n, n)].mean() for _ in range(n_boot)])
    boot_means.sort()
    return {
        "mean": float(arr.mean()),
        "ci_lo": float(boot_means[int(0.025 * n_boot)]),
        "ci_hi": float(boot_means[int(0.975 * n_boot)]),
    }


def consensus_construct(inst, high_thresh=0.7, medium_thresh=0.3):
    """Entity construction with LP-weighted decisions."""
    samples = inst["samples"]
    N = len(samples)

    entity_counts = Counter()
    entity_sample_indices = defaultdict(list)

    for i, s in enumerate(samples):
        seen = set()
        for e in s.get("entities", []):
            key = (e["start"], e["end"], e["type"])
            if key not in seen:
                entity_counts[key] += 1
                entity_sample_indices[key].append(i)
                seen.add(key)

    sample_lps = []
    for i, s in enumerate(samples):
        lp = s.get("mean_logprob")
        if lp is None and "logprobs" in inst and i < len(inst["logprobs"]):
            lp = inst["logprobs"][i]
        if lp is not None:
            sample_lps.append(lp)
